            nearest = None
            for rx, ry in res:
                d = cheb(nx, ny, rx, ry)
                if nearest is None or d < nearest:
                    nearest = d
            score_key = (nearest, -cheb(nx, ny, ox, oy), dx, dy)
        else:
            score_key = (cheb(nx, ny, ox, oy), dx, dy)
        if best is None or score_key < best[0]:
            best = (score_key, dx, dy)

    if best is None:
        return [0, 0]
    return [int(best[1]), int(best[2])]

